sp_widget.client_script:
function($scope, $rootScope) {
    var chartAmortizacaoInstance = null;

    $scope.anoSelecionadoAmortizacao = "";
    $scope.exibirGraficoAmortizacao = false;
    $scope.tipoGrafico = 'bar'; // era: line

    function carregarDadosAmortizacao() {
        var filtros = {
            ano: $scope.anoSelecionadoAmortizacao || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var listaAmortizacao = response.data.dadosAmortizacao || [];
            inicializarGraficoAmortizacao(listaAmortizacao);
        });
    }

    $rootScope.$on('filtroAnoIndicadoresSelecionado', function(event, ano) {
        $scope.anoSelecionadoAmortizacao = ano;

        // Se um ano foi selecionado, muda para gráfico de barra, senão volta para linha
        if (ano) {
            $scope.tipoGrafico = 'bar';
        } else {
            $scope.tipoGrafico = 'bar'; //era line
        }

        carregarDadosAmortizacao();
    });

    carregarDadosAmortizacao();

    function inicializarGraficoAmortizacao(listaAmortizacao) {
        if (!listaAmortizacao || listaAmortizacao.length === 0) {
            if (chartAmortizacaoInstance) {
                chartAmortizacaoInstance.destroy();
                chartAmortizacaoInstance = null;
            }
            $scope.exibirGraficoAmortizacao = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoAmortizacao = true;
        $scope.$applyAsync();

        var labels = [];
        var amortizacaoExternaData = [];
        var amortizacaoInternaData = [];
        var jurosEncargosExternaData = [];
        var jurosEncargosInternaData = [];

        for (var i = 0; i < listaAmortizacao.length; i++) {
            labels.push(listaAmortizacao[i].ano);
            amortizacaoExternaData.push(listaAmortizacao[i].amortizacaoExterna);
            amortizacaoInternaData.push(listaAmortizacao[i].amortizacaoInterna);
            jurosEncargosExternaData.push(listaAmortizacao[i].jurosEncargosExterna);
            jurosEncargosInternaData.push(listaAmortizacao[i].jurosEncargosInterna);
        }

        var canvas = document.getElementById('graficoAmortizacao');
        if (!canvas) {
            console.error("Elemento canvas 'graficoAmortizacao' não encontrado.");
            return;
        }

        var ctx = canvas.getContext('2d');

        if (chartAmortizacaoInstance) {
            chartAmortizacaoInstance.destroy();
        }

        chartAmortizacaoInstance = new Chart(ctx, {
            type: $scope.tipoGrafico,  // usa a variável para tipo
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Amortização Externa (milhões)',
                        data: amortizacaoExternaData,
                        borderColor: '#4A75B1',
                        backgroundColor: $scope.tipoGrafico === 'bar' ? '#4A75B1' : 'transparent',
                        borderWidth: 2,
                        borderDash: $scope.tipoGrafico === 'line' ? [6, 4] : [],
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    },
                    {
                        label: 'Amortização Interna (milhões)',
                        data: amortizacaoInternaData,
                        borderColor: '#6BB7F0',
                        backgroundColor: $scope.tipoGrafico === 'bar' ? '#6BB7F0' : 'transparent',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    },
                    {
                        label: 'Juros e Encargos Externa (milhões)',
                        data: jurosEncargosExternaData,
                        borderColor: '#293273',
                        backgroundColor: $scope.tipoGrafico === 'bar' ? '#293273' : 'transparent',
                        borderWidth: 2,
                        borderDash: $scope.tipoGrafico === 'line' ? [6, 4] : [],
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    },
                    {
                        label: 'Juros e Encargos Interna (milhões)',
                        data: jurosEncargosInternaData,
                        borderColor: '#137A8F',
                        backgroundColor: $scope.tipoGrafico === 'bar' ? '#137A8F' : 'transparent',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valores (em R$)'
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': ' + context.parsed.y.toFixed(2) + '';
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
		 input = input || {};
    var anoFiltro = input.ano || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_amortizacao_juros');
    if (anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }
    gr.orderBy('u_ano');
    gr.query();

    var listaAmortizacao = [];

    while (gr.next()) {
        listaAmortizacao.push({
            ano: gr.getValue('u_ano'),
            amortizacaoExterna: parseFloat(gr.getValue('u_amortizacao_externa')) / 1 || 0,
            amortizacaoInterna: parseFloat(gr.getValue('u_amortizacao_interna')) / 1 || 0,
            jurosEncargosExterna: parseFloat(gr.getValue('u_juros_encargos_externa')) / 1 || 0,
            jurosEncargosInterna: parseFloat(gr.getValue('u_juros_encargos_interna')) / 1 || 0
        });
    }

    data.dadosAmortizacao = listaAmortizacao;
})();
